import { motion } from 'framer-motion';
import {
  FiArrowRight,
  FiAward,
  FiClock,
  FiCpu,
  FiExternalLink,
  FiGrid,
  FiLayers,
  FiShield,
  FiTarget,
  FiUsers,
  FiZap
} from 'react-icons/fi';
import { useInView } from 'react-intersection-observer';
import { Link } from 'react-router-dom';
import SEO from '../components/SEO';

const Products = () => {
  const [heroRef, heroInView] = useInView({ triggerOnce: true, threshold: 0.1 });
  const [productsRef, productsInView] = useInView({ triggerOnce: true, threshold: 0.1 });

  const products = [
    {
      id: 'mini-hub',
      name: 'Arrotech Hub',
      tagline: 'Enterprise AI-Powered Marketing & Business Automation',
      description: 'A production-grade, AI-augmented full-stack platform implementing the Model Context Protocol (MCP) for seamless integration between Large Language Models and enterprise business tools.',
      url: 'https://hub.arrotechsolutions.com/',
      gradient: 'from-violet-500 to-indigo-600',
      icon: <FiCpu className="w-8 h-8" />,
      features: [
        { icon: <FiLayers className="w-5 h-5" />, title: 'Multi-LLM Support', description: 'OpenAI, Anthropic, Gemini, Ollama & more' },
        { icon: <FiZap className="w-5 h-5" />, title: 'Workflow Automation', description: 'NLP to workflow conversion with conditional logic' },
        { icon: <FiGrid className="w-5 h-5" />, title: '50+ Platform Integrations', description: 'HubSpot, Slack, Salesforce, Teams, Asana, GA4' },
        { icon: <FiTarget className="w-5 h-5" />, title: 'Autonomous Agents', description: 'Self-executing workflows with monitoring' }
      ],
      stats: [
        { value: '50+', label: 'Integrations' },
        { value: '6+', label: 'LLM Providers' },
        { value: '50+', label: 'API Endpoints' },
        { value: '24/7', label: 'Automation' }
      ],
    }
  ];

  return (
    <div className="bg-slate-950 min-h-screen pt-20">
      <SEO
        title="Our Products"
        description="Explore Arrotech's AI-powered platforms, including our flagship Arrotech Hub for business automation and model connectivity."
        canonical="/products"
      />
      {/* Hero Section */}
      <section ref={heroRef} className="relative py-24 overflow-hidden">
        {/* Background */}
        <div className="absolute inset-0">
          <div className="absolute inset-0 bg-gradient-to-b from-slate-950 via-slate-900 to-slate-950" />
          <div
            className="absolute inset-0 opacity-20"
            style={{
              backgroundImage: `
                linear-gradient(rgba(99, 102, 241, 0.1) 1px, transparent 1px),
                linear-gradient(90deg, rgba(99, 102, 241, 0.1) 1px, transparent 1px)
              `,
              backgroundSize: '60px 60px'
            }}
          />
          <div className="absolute top-1/4 left-1/4 w-[600px] h-[600px] bg-violet-600/20 rounded-full blur-[150px]" />
          <div className="absolute bottom-1/4 right-1/4 w-[500px] h-[500px] bg-blue-600/20 rounded-full blur-[120px]" />
        </div>

        <div className="container relative z-10">
          <motion.div
            initial={{ opacity: 0, y: 30 }}
            animate={heroInView ? { opacity: 1, y: 0 } : {}}
            transition={{ duration: 0.8 }}
            className="max-w-4xl mx-auto text-center"
          >
            <div className="inline-flex items-center gap-2 px-4 py-2 rounded-full bg-white/5 backdrop-blur-sm border border-white/10 mb-8">
              <span className="w-2 h-2 bg-emerald-400 rounded-full animate-pulse" />
              <span className="text-slate-300 text-sm font-medium">Live Products</span>
            </div>

            <h1 className="text-5xl md:text-7xl font-bold mb-6 leading-tight">
              <span className="text-white">Our AI-Powered</span>
              <br />
              <span className="bg-gradient-to-r from-violet-400 via-blue-400 to-cyan-400 bg-clip-text text-transparent">
                Solutions
              </span>
            </h1>

            <p className="text-xl md:text-2xl text-slate-400 mb-10 max-w-3xl mx-auto leading-relaxed">
              Discover our suite of production-ready platforms transforming businesses across industries
            </p>

            <div className="flex flex-wrap justify-center gap-4">
              {products.map((product) => (
                <motion.a
                  key={product.id}
                  href={`#${product.id}`}
                  whileHover={{ scale: 1.05, y: -2 }}
                  whileTap={{ scale: 0.98 }}
                  className={`px-6 py-3 rounded-xl bg-gradient-to-r ${product.gradient} text-white font-medium shadow-lg hover:shadow-xl transition-all duration-300`}
                >
                  {product.name}
                </motion.a>
              ))}
            </div>
          </motion.div>
        </div>
      </section>

      {/* Products Section */}
      <section ref={productsRef} className="py-24">
        <div className="container">
          <div className="space-y-32">
            {products.map((product, index) => (
              <motion.div
                key={product.id}
                id={product.id}
                initial={{ opacity: 0, y: 50 }}
                animate={productsInView ? { opacity: 1, y: 0 } : {}}
                transition={{ duration: 0.8, delay: index * 0.2 }}
                className="scroll-mt-24"
              >
                <div className="bg-slate-900/50 backdrop-blur-sm border border-slate-800 rounded-3xl overflow-hidden">
                  {/* Header */}
                  <div className={`relative p-8 md:p-12 bg-gradient-to-r ${product.gradient}`}>
                    <div className="absolute inset-0 opacity-10">
                      <div className="absolute inset-0" style={{
                        backgroundImage: `radial-gradient(circle at 2px 2px, white 1px, transparent 0)`,
                        backgroundSize: '24px 24px'
                      }} />
                    </div>

                    <div className="relative z-10 flex flex-col md:flex-row md:items-center md:justify-between gap-6">
                      <div className="flex items-center gap-4">
                        <div className="w-16 h-16 bg-white/20 backdrop-blur-sm rounded-2xl flex items-center justify-center text-white">
                          {product.icon}
                        </div>
                        <div>
                          <h2 className="text-3xl md:text-4xl font-bold text-white mb-1">
                            {product.name}
                          </h2>
                          <p className="text-white/80 text-lg">
                            {product.tagline}
                          </p>
                        </div>
                      </div>

                      <motion.a
                        href={product.url}
                        target="_blank"
                        rel="noopener noreferrer"
                        whileHover={{ scale: 1.05 }}
                        whileTap={{ scale: 0.98 }}
                        className="inline-flex items-center gap-2 px-6 py-3 bg-white text-slate-900 rounded-xl font-semibold shadow-lg hover:shadow-xl transition-all duration-300"
                      >
                        Visit Platform
                        <FiExternalLink className="w-5 h-5" />
                      </motion.a>
                    </div>
                  </div>

                  {/* Content */}
                  <div className="p-8 md:p-12">
                    <p className="text-slate-400 text-lg mb-10 max-w-3xl leading-relaxed">
                      {product.description}
                    </p>

                    {/* Stats Grid */}
                    <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-10">
                      {product.stats.map((stat, statIndex) => (
                        <motion.div
                          key={statIndex}
                          initial={{ opacity: 0, scale: 0.9 }}
                          animate={productsInView ? { opacity: 1, scale: 1 } : {}}
                          transition={{ duration: 0.5, delay: 0.3 + statIndex * 0.1 }}
                          className="p-5 rounded-2xl bg-slate-800/50 text-center"
                        >
                          <div className={`text-2xl md:text-3xl font-bold bg-clip-text text-transparent bg-gradient-to-r ${product.gradient} mb-1`}>
                            {stat.value}
                          </div>
                          <div className="text-sm text-slate-500">
                            {stat.label}
                          </div>
                        </motion.div>
                      ))}
                    </div>

                    {/* Features Grid */}
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                      {product.features.map((feature, featureIndex) => (
                        <motion.div
                          key={featureIndex}
                          initial={{ opacity: 0, x: -20 }}
                          animate={productsInView ? { opacity: 1, x: 0 } : {}}
                          transition={{ duration: 0.5, delay: 0.4 + featureIndex * 0.1 }}
                          className="flex items-start gap-4 p-5 rounded-2xl bg-slate-800/30 border border-slate-700/50 hover:border-slate-600 transition-all duration-300"
                        >
                          <div className={`w-12 h-12 rounded-xl bg-gradient-to-br ${product.gradient} flex items-center justify-center text-white flex-shrink-0 shadow-lg`}>
                            {feature.icon}
                          </div>
                          <div>
                            <h4 className="font-semibold text-white mb-1">
                              {feature.title}
                            </h4>
                            <p className="text-sm text-slate-500">
                              {feature.description}
                            </p>
                          </div>
                        </motion.div>
                      ))}
                    </div>




                  </div>
                </div>
              </motion.div>
            ))}
          </div>
        </div>
      </section>

      {/* CTA Section */}
      <section className="py-24 relative overflow-hidden">
        <div className="absolute inset-0">
          <div className="absolute inset-0 bg-gradient-to-br from-violet-600/20 via-blue-600/20 to-cyan-600/20" />
          <div
            className="absolute inset-0 opacity-30"
            style={{
              backgroundImage: `radial-gradient(circle at 2px 2px, rgba(255,255,255,0.1) 1px, transparent 0)`,
              backgroundSize: '32px 32px'
            }}
          />
        </div>

        <div className="container relative z-10">
          <motion.div
            initial={{ opacity: 0, y: 30 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            transition={{ duration: 0.8 }}
            className="max-w-4xl mx-auto text-center"
          >
            <div className="inline-flex items-center gap-2 px-4 py-2 rounded-full bg-white/10 backdrop-blur-sm border border-white/20 text-white/90 text-sm font-medium mb-6">
              <FiAward className="w-4 h-4" />
              Custom Solutions Available
            </div>

            <h2 className="text-4xl md:text-5xl font-bold text-white mb-6">
              Need a Custom AI Solution?
            </h2>

            <p className="text-xl text-slate-300 mb-10 max-w-2xl mx-auto">
              We specialize in building tailored AI platforms for your unique business needs.
            </p>

            <div className="flex flex-col sm:flex-row items-center justify-center gap-4">
              <motion.div whileHover={{ scale: 1.02 }} whileTap={{ scale: 0.98 }}>
                <Link
                  to="/contact"
                  className="inline-flex items-center gap-2 px-8 py-4 bg-white text-slate-900 rounded-xl font-semibold shadow-lg hover:shadow-xl transition-all duration-300"
                >
                  Start a Project
                  <FiArrowRight className="w-5 h-5" />
                </Link>
              </motion.div>

              <motion.div whileHover={{ scale: 1.02 }} whileTap={{ scale: 0.98 }}>
                <Link
                  to="/services"
                  className="inline-flex items-center gap-2 px-8 py-4 bg-white/10 backdrop-blur-sm border border-white/20 text-white rounded-xl font-semibold hover:bg-white/20 transition-all duration-300"
                >
                  View Services
                </Link>
              </motion.div>
            </div>

            {/* Trust indicators */}
            <div className="mt-16 grid grid-cols-2 md:grid-cols-4 gap-6">
              {[
                { icon: <FiClock className="w-6 h-6" />, label: '24/7 Support' },
                { icon: <FiShield className="w-6 h-6" />, label: 'Secure & Reliable' },
                { icon: <FiZap className="w-6 h-6" />, label: 'Fast Delivery' },
                { icon: <FiUsers className="w-6 h-6" />, label: 'Expert Team' }
              ].map((item, index) => (
                <motion.div
                  key={index}
                  initial={{ opacity: 0, y: 20 }}
                  whileInView={{ opacity: 1, y: 0 }}
                  viewport={{ once: true }}
                  transition={{ duration: 0.5, delay: index * 0.1 }}
                  className="flex flex-col items-center gap-2 text-slate-400"
                >
                  <div className="w-12 h-12 rounded-xl bg-slate-800 flex items-center justify-center">
                    {item.icon}
                  </div>
                  <span className="text-sm font-medium">{item.label}</span>
                </motion.div>
              ))}
            </div>
          </motion.div>
        </div>
      </section>
    </div>
  );
};

export default Products;
